import{_ as o,o as n,c as e,a3 as s,j as t}from"./chunks/framework.Cc-oPviL.js";const g=JSON.parse('{"title":"01 · 进程与线程：谁在跑，跑的时候带着什么","description":"","frontmatter":{},"headers":[],"relativePath":"bagu/os/01.md","filePath":"bagu/os/01.md"}'),l={name:"bagu/os/01.md"};function r(i,a,p,c,d,u){return n(),e("div",null,[...a[0]||(a[0]=[s('<h1 id="_01-·-进程与线程-谁在跑-跑的时候带着什么" tabindex="-1">01 · 进程与线程：谁在跑，跑的时候带着什么 <a class="header-anchor" href="#_01-·-进程与线程-谁在跑-跑的时候带着什么" aria-label="Permalink to &quot;01 · 进程与线程：谁在跑，跑的时候带着什么&quot;">​</a></h1><blockquote><p>这一篇是 OS 模块的地基。后面的内存、锁、IO，主体都是这里的&quot;进程/线程&quot;。</p></blockquote><h2 id="一句话本质" tabindex="-1">一句话本质 <a class="header-anchor" href="#一句话本质" aria-label="Permalink to &quot;一句话本质&quot;">​</a></h2><p><strong>进程 = 一个正在运行的程序 + 它独占的一套资源（地址空间、文件表）</strong>。线程 = 进程内部真正被 CPU 执行的那条流水线。</p><h2 id="生活类比-餐厅里的订单" tabindex="-1">生活类比：餐厅里的订单 <a class="header-anchor" href="#生活类比-餐厅里的订单" aria-label="Permalink to &quot;生活类比：餐厅里的订单&quot;">​</a></h2><ul><li><strong>程序</strong>（存在硬盘上的 exe）：菜谱。放在那里不动，不会做菜。</li><li><strong>进程</strong>：一桌客人下的单。有独立的食材（内存）、独立的进度（执行到哪一步）、独立的账单（资源）。</li><li><strong>线程</strong>：这一桌订单里的几道菜。<strong>共用同一份食材和同一个操作台</strong>，但可以几条流水线同时做。</li><li><strong>PCB（进程控制块）</strong>：这张订单的小票。内核靠它知道&quot;这桌做到哪了、食材放在哪&quot;。</li><li><strong>上下文切换</strong>：厨师从做这桌换到做那桌。得先把当前这桌的进度记下来（保存寄存器），再把那桌的进度恢复（恢复寄存器）。</li></ul><p>关键差别一句话：<strong>换一桌客人（换进程）要清空整个操作台；同一桌换一道菜（换线程）不用。</strong></p><h2 id="核心机制" tabindex="-1">核心机制 <a class="header-anchor" href="#核心机制" aria-label="Permalink to &quot;核心机制&quot;">​</a></h2><h3 id="一、进程的状态机" tabindex="-1">一、进程的状态机 <a class="header-anchor" href="#一、进程的状态机" aria-label="Permalink to &quot;一、进程的状态机&quot;">​</a></h3><p>一个进程从创建到消亡，只会走下面这几条边：</p>',10),t("figure",{class:"fig"},[t("span",{class:"fig-hint"},"← 左右滑动看完整图 →"),t("svg",{viewBox:"0 0 680 300",width:"100%",xmlns:"http://www.w3.org/2000/svg",role:"img","aria-label":"进程五状态转换图"},[t("defs",null,[t("marker",{id:"arw-fsm",viewBox:"0 0 10 10",markerWidth:"9",markerHeight:"9",refX:"8.5",refY:"5",markerUnits:"userSpaceOnUse",orient:"auto"},[t("path",{d:"M2 1.5 L8 5 L2 8.5",class:"f-line",fill:"none","stroke-linecap":"round","stroke-linejoin":"round"})])]),t("path",{class:"f-line",d:"M88 74 V120","marker-end":"url(#arw-fsm)"}),t("path",{class:"f-line",d:"M152 133 H300","marker-end":"url(#arw-fsm)"}),t("path",{class:"f-line",d:"M348 120 C348 88 128 88 128 120","marker-end":"url(#arw-fsm)"}),t("path",{class:"f-line",d:"M348 166 V236","marker-end":"url(#arw-fsm)"}),t("path",{class:"f-line",d:"M396 143 H520","marker-end":"url(#arw-fsm)"}),t("path",{class:"f-line",d:"M300 259 H216 V155 H152","marker-end":"url(#arw-fsm)"}),t("rect",{class:"f-box",x:"40",y:"28",width:"96",height:"46",rx:"8"}),t("text",{class:"f-title",x:"88",y:"56","text-anchor":"middle"},"新建"),t("rect",{class:"f-box",x:"56",y:"120",width:"96",height:"46",rx:"8"}),t("text",{class:"f-title",x:"104",y:"148","text-anchor":"middle"},"就绪"),t("rect",{class:"f-box-hi",x:"300",y:"120",width:"96",height:"46",rx:"8"}),t("text",{class:"f-title",x:"348",y:"148","text-anchor":"middle"},"运行"),t("rect",{class:"f-box",x:"300",y:"236",width:"96",height:"46",rx:"8"}),t("text",{class:"f-title",x:"348",y:"264","text-anchor":"middle"},"阻塞"),t("rect",{class:"f-box",x:"520",y:"120",width:"96",height:"46",rx:"8"}),t("text",{class:"f-title",x:"568",y:"148","text-anchor":"middle"},"终止"),t("text",{class:"f-label",x:"100",y:"101"},"分配资源完成"),t("text",{class:"f-label",x:"226",y:"125","text-anchor":"middle"},"被调度器选中"),t("text",{class:"f-label",x:"238",y:"84","text-anchor":"middle"},"时间片用完 / 被抢占"),t("text",{class:"f-label",x:"360",y:"206"},"等待 IO / 锁 / 信号"),t("text",{class:"f-label",x:"458",y:"135","text-anchor":"middle"},"主动退出"),t("text",{class:"f-label",x:"258",y:"251","text-anchor":"middle"},"事件到达")]),t("figcaption",{class:"fig-cap"},"五个状态之间只有这 6 条合法转换。面试最爱追问「阻塞能不能直接到运行」——不能，事件到达后只能先回就绪队列，等调度器再选一次。")],-1),s(`<p><strong>三个必考点</strong>：</p><ol><li><strong>阻塞 &gt; 就绪，不能直接 &gt; 运行</strong>。因为事件到达时 CPU 可能正忙，必须重新排队等调度。这是最高频的细节坑。</li><li><strong>就绪和阻塞的区别</strong>：就绪是&quot;只差 CPU&quot;，阻塞是&quot;CPU 给我也没用，我在等别的东西&quot;。</li><li><strong>运行 &gt; 就绪</strong>是时间片用完（被动），<strong>运行 &gt; 阻塞</strong>是自己发起 IO（主动）。</li></ol><h3 id="二、pcb-里存了什么" tabindex="-1">二、PCB 里存了什么 <a class="header-anchor" href="#二、pcb-里存了什么" aria-label="Permalink to &quot;二、PCB 里存了什么&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+-- PID / 父进程 PID</span></span>
<span class="line"><span>+-- 进程状态（就绪 / 运行 / 阻塞）</span></span>
<span class="line"><span>+-- 程序计数器 PC（下一条指令）</span></span>
<span class="line"><span>+-- 寄存器现场（通用寄存器、栈指针）</span></span>
<span class="line"><span>+-- 内存管理信息（页表基址）</span></span>
<span class="line"><span>+-- 打开的文件表</span></span>
<span class="line"><span>+-- 优先级 / 时间片 / 统计信息</span></span></code></pre></div><p><strong>PCB 是进程存在的唯一标志</strong>。所谓&quot;创建进程&quot;，内核动作就是&quot;分配并初始化一个 PCB&quot;。</p><h3 id="三、线程共享什么、独占什么-必背" tabindex="-1">三、线程共享什么、独占什么（必背） <a class="header-anchor" href="#三、线程共享什么、独占什么-必背" aria-label="Permalink to &quot;三、线程共享什么、独占什么（必背）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>独占（每个线程一份）</th><th>共享（同进程内所有线程共用）</th></tr></thead><tbody><tr><td>程序计数器 PC</td><td>代码段</td></tr><tr><td>寄存器现场</td><td>全局变量 / 静态变量</td></tr><tr><td>栈（函数调用、局部变量）</td><td>堆（new 出来的对象）</td></tr><tr><td>线程 ID、状态</td><td>打开的文件描述符</td></tr><tr><td>错误码 errno</td><td>信号处理器</td></tr></tbody></table><p><strong>一句话记忆</strong>：<strong>栈是私有的，堆是共享的</strong>。所以&quot;局部变量天然线程安全，成员变量不是&quot;——这不是语言规定，是内存布局决定的。</p><h3 id="四、上下文切换到底切了什么" tabindex="-1">四、上下文切换到底切了什么 <a class="header-anchor" href="#四、上下文切换到底切了什么" aria-label="Permalink to &quot;四、上下文切换到底切了什么&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>进程 A 在跑</span></span>
<span class="line"><span>   v 时间片用完 / 主动让出</span></span>
<span class="line"><span>1. 保存 A 的寄存器到 A 的 PCB          &lt; 纯 CPU 操作，很快</span></span>
<span class="line"><span>2. 切换内核栈</span></span>
<span class="line"><span>3. 加载 B 的 PCB 里的寄存器</span></span>
<span class="line"><span>4. 切换页表（CR3 寄存器）              &lt; 贵！会刷 TLB</span></span>
<span class="line"><span>5. 刷新流水线 / 分支预测器             &lt; 贵！</span></span>
<span class="line"><span>   v</span></span>
<span class="line"><span>进程 B 开始跑</span></span></code></pre></div><p><strong>进程切换 vs 线程切换的差别就在第 4 步</strong>：同进程内的线程共享页表，不用切，所以<strong>线程切换比进程切换便宜得多</strong>。这是&quot;线程比进程轻量&quot;的真正原因，不是&quot;线程小&quot;这种含糊说法。</p><h3 id="五、协程-比线程更轻" tabindex="-1">五、协程：比线程更轻 <a class="header-anchor" href="#五、协程-比线程更轻" aria-label="Permalink to &quot;五、协程：比线程更轻&quot;">​</a></h3><p>线程的切换由<strong>内核</strong>决定（抢占式），协程的切换由<strong>程序自己</strong>决定（协作式）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>线程：内核说&quot;你该下了&quot; &gt; 用户程序无法拒绝 &gt; 有内核开销</span></span>
<span class="line"><span>协程：程序说&quot;我要等 IO 了&quot; &gt; 主动让出 &gt; 纯用户态切换，几十纳秒</span></span></code></pre></div><p>代价：协程不能利用多核（一个线程内的协程是串行的），而且一个协程如果死循环不让出，整个线程都卡住。</p><h2 id="为什么这么设计" tabindex="-1">为什么这么设计 <a class="header-anchor" href="#为什么这么设计" aria-label="Permalink to &quot;为什么这么设计&quot;">​</a></h2><h3 id="为什么要-进程-这层隔离" tabindex="-1">为什么要&quot;进程&quot;这层隔离？ <a class="header-anchor" href="#为什么要-进程-这层隔离" aria-label="Permalink to &quot;为什么要&quot;进程&quot;这层隔离？&quot;">​</a></h3><p><strong>反事实</strong>：如果没有进程，所有程序共享一个地址空间。</p><ul><li>A 程序写地址 <code>0x1000</code>，B 程序也写 <code>0x1000</code> &gt; 互相覆盖 &gt; A 崩了会带崩 B。</li><li>A 程序有个野指针，能直接改掉 B 的数据库连接 &gt; 一个 bug 变成安全事故。</li><li>一个程序内存泄漏，把整台机器吃光 &gt; 所有程序一起死。</li></ul><p>进程通过<strong>独立的地址空间</strong>（02 篇的虚拟内存）解决这一切：每个进程都以为自己独占 <code>0x0</code> 到 <code>0xFFFFFFFF</code>。</p><h3 id="为什么进程里还要有线程" tabindex="-1">为什么进程里还要有线程？ <a class="header-anchor" href="#为什么进程里还要有线程" aria-label="Permalink to &quot;为什么进程里还要有线程？&quot;">​</a></h3><p><strong>反事实</strong>：如果只有进程，没有线程。</p><ul><li>一个 Web 服务器要同时处理 1000 个请求 &gt; 得开 1000 个进程 &gt; 每个进程一套独立地址空间 &gt; 内存爆炸，切换开销爆炸。</li><li>一个进程内想&quot;边算边响应用户点击&quot; &gt; 做不到，只能等算完。</li></ul><p>线程让<strong>同一份资源被多条流水线共用</strong>：1000 个请求共享同一份代码和缓存，切换还便宜。</p><h3 id="为什么要协程" tabindex="-1">为什么要协程？ <a class="header-anchor" href="#为什么要协程" aria-label="Permalink to &quot;为什么要协程？&quot;">​</a></h3><p><strong>反事实</strong>：如果用线程做高并发。</p><ul><li>每个线程默认栈 1MB，1 万个线程 = 10GB 内存，直接崩。</li><li>线程切换要走内核，一次几微秒，1 万线程频繁切换，CPU 全花在切换上。</li></ul><p>协程把栈做到几 KB 且按需增长，切换在用户态完成。这就是 Go 的 goroutine 能做到百万级并发的原因。</p><h2 id="面试怎么问" tabindex="-1">面试怎么问 <a class="header-anchor" href="#面试怎么问" aria-label="Permalink to &quot;面试怎么问&quot;">​</a></h2><p><strong>Q：进程和线程的区别？</strong> 别只答&quot;进程是资源分配单位，线程是调度单位&quot;——这是第一层，人人都会。要接上：</p><blockquote><p>更本质的差别在<strong>隔离与开销</strong>：进程有独立地址空间，所以隔离强、切换贵（要换页表、刷 TLB）；线程共享地址空间，隔离弱（一个线程野指针能搞崩整个进程）、切换便宜。</p></blockquote><p><strong>Q：一个进程最多能创建多少线程？</strong></p><blockquote><p>理论上受三样限制：① 虚拟地址空间（每线程栈默认 1~8MB）；② 内核参数（<code>/proc/sys/kernel/threads-max</code>）；③ 系统内存。实际瓶颈通常是内存，不是&quot;数量上限&quot;。</p></blockquote><p><strong>Q：线程越多越好吗？</strong></p><blockquote><p>不是。线程数超过 CPU 核数后，多出来的线程只会增加切换开销和锁竞争。CPU 密集型任务，线程数 ≈ 核数；IO 密集型可以多一些（因为线程大部分时间在阻塞）。</p></blockquote><p><strong>Q：fork 之后父子进程共享什么？</strong></p><blockquote><p>共享<strong>代码段</strong>（只读），<strong>不共享</strong>数据。但 Linux 用 <strong>写时复制（COW）</strong>：fork 时父子页表指向同一批物理页，且标记为只读；任一方写入时触发缺页，内核才真正复制那一页。 所以 fork 很快，且&quot;读多写少&quot;的场景几乎不花额外内存。</p></blockquote><p><strong>追问链</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>进程和线程区别？</span></span>
<span class="line"><span>  &gt; 线程共享什么？（栈私有、堆共享）</span></span>
<span class="line"><span>    &gt; 为什么栈私有？（每个线程要有独立的函数调用链）</span></span>
<span class="line"><span>      &gt; 那局部变量一定线程安全吗？（不一定，如果它是指向堆的引用/被取地址传出去）</span></span>
<span class="line"><span>        &gt; 那怎么保证共享数据安全？（锁 &gt; 03 篇）</span></span>
<span class="line"><span>          &gt; 锁多了会怎样？（死锁 &gt; 03 篇；性能下降 &gt; 锁粒度）</span></span></code></pre></div><h2 id="和其他知识的连接" tabindex="-1">和其他知识的连接 <a class="header-anchor" href="#和其他知识的连接" aria-label="Permalink to &quot;和其他知识的连接&quot;">​</a></h2><ul><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/os/00">操作系统导读：一台机器内部在忙什么</a>：进程是 OS 五篇的主体</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/os/02">虚拟内存：让每个程序都以为自己独占一台机器</a>：每个进程一套独立页表，是&quot;进程隔离&quot;的实现手段</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/os/03">调度与并发同步：CPU 分给谁，共享数据谁先动</a>：线程是调度的基本单位；共享堆导致需要锁</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/os/04">IO 模型与零拷贝：等设备的时候，CPU 在干什么</a>：进程发起 IO 后进入阻塞态，就是本篇状态机里的那条边</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/os/05">内核态与系统调用：用户程序怎么&quot;申请&quot;做事</a>：创建进程（fork）、创建线程（clone）都是系统调用</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/db/04">锁与死锁</a>：数据库连接池的线程模型，本质是这里的权衡</li></ul><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：为什么&quot;阻塞 &gt; 就绪&quot;不能直接变成&quot;运行&quot;？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为 CPU 可能正被别的进程占着。IO 完成只是&quot;这个进程具备运行条件了&quot;，但能不能立刻上 CPU，得由调度器决定。</p><p>如果直接跳到运行，就相当于&quot;事件一到就抢占 CPU&quot;，会破坏调度策略（比如优先级、公平性），也容易让刚唤醒的进程立刻又被打断。</p><p>所以标准路径是：<strong>阻塞 &gt; 就绪 &gt; （排队）&gt; 运行</strong>。</p></details><p><strong>Q2：进程切换比线程切换贵在哪一步？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>贵在<strong>切换页表</strong>。</p><p>线程共享同一套页表，切换时只要换寄存器现场；进程有各自的页表，切换要改 CR3 寄存器指向新页表，这会导致 <strong>TLB（地址翻译缓存）失效</strong>——之前缓存的&quot;虚拟页&gt;物理页&quot;映射全作废，接下来一段时间每次访存都要重新查页表，程序明显变慢。</p><p>此外流水线和分支预测器也要冲刷。所以进程切换的开销通常是线程切换的几倍到几十倍。</p></details><p><strong>Q3：局部变量一定线程安全吗？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p><strong>不一定</strong>，这里有两个坑：</p><ol><li>如果局部变量是<strong>引用类型</strong>，它本身在栈上，但指向的对象在堆上。多个线程拿到同一个引用，就共享了那个对象。</li><li>如果局部变量的地址被传出去（比如取地址赋给全局变量、或者传给另一个线程），那它就不再&quot;私有&quot;了。</li></ol><p>所以准确说法是：<strong>栈上的值本身是私有的，但栈上的引用可能指向共享数据</strong>。</p></details><h2 id="类比失效处-易错点" tabindex="-1">类比失效处 / 易错点 <a class="header-anchor" href="#类比失效处-易错点" aria-label="Permalink to &quot;类比失效处 / 易错点&quot;">​</a></h2><ul><li><strong>&quot;一桌订单&quot;会让人以为进程之间有共享</strong>。实际上进程地址空间完全隔离，共享必须显式申请（共享内存 <code>shm</code>）。</li><li><strong>&quot;换菜不用清操作台&quot;不完全对</strong>。线程切换虽然不换页表，但<strong>寄存器现场必须换</strong>，而且如果两个线程跑在不同核上，还会涉及缓存行的迁移（伪共享问题）。</li><li><strong>&quot;线程比进程轻量&quot;不等于&quot;线程可以无限开&quot;</strong>。默认栈 1MB，1 万线程就是 10GB 虚拟地址空间，32 位系统直接不够用。</li><li><strong>fork 之后子进程从哪开始执行？</strong> 不是从头，是从 fork 返回处。父子进程的 fork 返回值不同（父得到子 PID，子得到 0），这是区分两者的标准做法。</li><li><strong>僵尸进程 vs 孤儿进程</strong>：僵尸是子进程死了但父进程没 wait（占着 PCB）；孤儿是父进程先死，子进程被 init/systemd 收养。两者方向相反，别混。</li></ul><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能默画进程 5 状态转换图，并说清每条箭头的触发条件（尤其&quot;阻塞只能到就绪&quot;）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能说出 PCB 里至少 5 项内容，并解释&quot;为什么 PCB 是进程存在的唯一标志&quot;</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能不看资料列出线程独占的 3 样、共享的 3 样，并说出&quot;栈私有堆共享&quot;的由来</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能解释进程切换比线程切换贵在哪一步（要说出页表和 TLB，不能只说&quot;开销大&quot;）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 能用&quot;反事实&quot;讲清：没有进程隔离会出什么事、没有线程会出什么事</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="5"> 能说出 fork 的写时复制机制，以及它为什么让 fork 很快</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="6"> 合上书，用自己的话讲 3 分钟，中途不卡壳</li></ul>`,52)])])}const q=o(l,[["render",r]]);export{g as __pageData,q as default};
